mapper.select:
SELECT id, name, type, discount_type, discount_value, min_spend, max_discount, total_count, remain_count, limit_per_user, valid_days, start_time, end_time, status, scope_type, scope_ids, create_time, update_time FROM coupon_template
AND name LIKE CONCAT('%', #{query.name}, '%')
AND type = #{query.type}
AND status = #{query.status}
ORDER BY create_time DESC
